\set ON_ERROR_STOP on
SET ROLE hospital_owner;
SET search_path=pg_catalog,ext,public;
BEGIN;
CREATE FUNCTION iam.has_patient_access(p_patient_id bigint,p_purpose text DEFAULT 'treatment') RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$ SELECT EXISTS(SELECT FROM iam.application_user u JOIN iam.user_role ur ON ur.user_id=u.id WHERE u.database_principal=session_user AND u.active AND ((p_purpose='treatment' AND ur.role_code='clinician') OR (p_purpose='registration' AND ur.role_code='registrar') OR (p_purpose='billing' AND ur.role_code='billing')) AND (EXISTS(SELECT FROM iam.access_grant g WHERE g.user_id=u.id AND g.patient_id=p_patient_id AND g.purpose=p_purpose AND statement_timestamp()<@g.valid_during) OR (p_purpose='treatment' AND EXISTS(SELECT FROM iam.break_glass b WHERE b.user_id=u.id AND b.patient_id=p_patient_id AND statement_timestamp()<@b.valid_during)))) $$;
CREATE FUNCTION audit.capture_change() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE oldj jsonb; newj jsonb; keyj jsonb; cols text[]; BEGIN IF TG_OP<>'INSERT' THEN oldj=to_jsonb(OLD); END IF; IF TG_OP<>'DELETE' THEN newj=to_jsonb(NEW); END IF; SELECT jsonb_object_agg(key,value) INTO keyj FROM jsonb_each(coalesce(newj,oldj)) WHERE key=ANY(TG_ARGV); IF TG_OP='UPDATE' THEN SELECT array_agg(key ORDER BY key) INTO cols FROM jsonb_each(newj) WHERE value IS DISTINCT FROM oldj->key; END IF; INSERT INTO audit.event(actor,transaction_id,table_schema,table_name,operation,entity_key,changed_columns,request_id) VALUES(session_user,txid_current(),TG_TABLE_SCHEMA,TG_TABLE_NAME,TG_OP,coalesce(keyj,'{}'),cols,left(current_setting('app.request_id',true),100)); IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW; END$$;
CREATE TRIGGER audit_events_immutable BEFORE UPDATE OR DELETE ON audit.event FOR EACH ROW EXECUTE FUNCTION ops.deny_mutation();
CREATE TRIGGER audit_access_immutable BEFORE UPDATE OR DELETE ON audit.access_event FOR EACH ROW EXECUTE FUNCTION ops.deny_mutation();
-- Baseline is explicitly marked: generated historical records are not fabricated audit history.
INSERT INTO audit.event(actor,transaction_id,table_schema,table_name,operation,entity_key,details) SELECT session_user,txid_current(),n.nspname,c.relname,'BASELINE','{}',jsonb_build_object('source','deterministic synthetic generator','loaded_before_audit_activation',true) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE c.relkind IN('r','p') AND NOT c.relispartition AND n.nspname IN('ref','org','mpi','ehr','adt','scheduling','lab','imaging','pharmacy','inventory','billing','quality','iam','integration');
DO $$DECLARE r record; args text; BEGIN FOR r IN SELECT c.oid,n.nspname,c.relname FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE c.relkind IN('r','p') AND NOT c.relispartition AND n.nspname IN('ref','org','mpi','ehr','adt','scheduling','lab','imaging','pharmacy','inventory','billing','quality','iam','integration') LOOP SELECT string_agg(quote_literal(k.attname),',' ORDER BY k.attname) INTO args FROM (SELECT a.attname FROM pg_constraint p JOIN pg_attribute a ON a.attrelid=p.conrelid AND a.attnum=ANY(p.conkey) WHERE p.conrelid=r.oid AND p.contype='p' UNION SELECT 'patient_id' WHERE EXISTS(SELECT FROM pg_attribute WHERE attrelid=r.oid AND attname='patient_id' AND NOT attisdropped))k; EXECUTE format('CREATE TRIGGER audit_change AFTER INSERT OR UPDATE OR DELETE ON %I.%I FOR EACH ROW EXECUTE FUNCTION audit.capture_change(%s)',r.nspname,r.relname,coalesce(args,'')); END LOOP; END$$;
-- Every patient-bearing table is protected, even tables with no runtime grant today.
DO $$DECLARE r record; p text; BEGIN FOR r IN SELECT n.nspname,c.relname FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace JOIN pg_attribute a ON a.attrelid=c.oid AND a.attname='patient_id' AND NOT a.attisdropped WHERE c.relkind IN('r','p') AND NOT c.relispartition AND n.nspname IN('mpi','ehr','adt','scheduling','lab','imaging','pharmacy','billing','quality','iam','audit') LOOP EXECUTE format('ALTER TABLE %I.%I ENABLE ROW LEVEL SECURITY',r.nspname,r.relname); EXECUTE format('ALTER TABLE %I.%I FORCE ROW LEVEL SECURITY',r.nspname,r.relname); EXECUTE format('CREATE POLICY owner_access ON %I.%I TO hospital_owner USING(true) WITH CHECK(true)',r.nspname,r.relname); IF r.nspname NOT IN('iam','audit') THEN EXECUTE format('CREATE POLICY clinician_access ON %I.%I TO hospital_clinician USING(iam.has_patient_access(patient_id,''treatment'')) WITH CHECK(iam.has_patient_access(patient_id,''treatment''))',r.nspname,r.relname); IF r.nspname IN('mpi','scheduling') THEN EXECUTE format('CREATE POLICY registrar_access ON %I.%I TO hospital_registrar USING(iam.has_patient_access(patient_id,''registration'')) WITH CHECK(iam.has_patient_access(patient_id,''registration''))',r.nspname,r.relname); END IF; IF r.nspname='billing' THEN EXECUTE format('CREATE POLICY billing_access ON %I.%I TO hospital_billing USING(iam.has_patient_access(patient_id,''billing'')) WITH CHECK(iam.has_patient_access(patient_id,''billing''))',r.nspname,r.relname); END IF; END IF; END LOOP; END$$;
ALTER TABLE mpi.patient ENABLE ROW LEVEL SECURITY;
ALTER TABLE mpi.patient FORCE ROW LEVEL SECURITY;
CREATE POLICY owner_access ON mpi.patient TO hospital_owner USING(true) WITH CHECK(true);
CREATE POLICY clinician_access ON mpi.patient TO hospital_clinician USING(iam.has_patient_access(id,'treatment')) WITH CHECK(iam.has_patient_access(id,'treatment'));
CREATE POLICY registrar_access ON mpi.patient TO hospital_registrar USING(iam.has_patient_access(id,'registration')) WITH CHECK(iam.has_patient_access(id,'registration'));
-- Dependent tables without a direct patient column inherit the parent visibility.
ALTER TABLE ehr.note_version ENABLE ROW LEVEL SECURITY;
ALTER TABLE ehr.note_version FORCE ROW LEVEL SECURITY;
CREATE POLICY owner_access ON ehr.note_version TO hospital_owner USING(true) WITH CHECK(true);
CREATE POLICY clinician_access ON ehr.note_version TO hospital_clinician USING(EXISTS(SELECT FROM ehr.clinical_note n WHERE n.id=note_id)) WITH CHECK(EXISTS(SELECT FROM ehr.clinical_note n WHERE n.id=note_id));
ALTER TABLE ehr.encounter_participant ENABLE ROW LEVEL SECURITY;
ALTER TABLE ehr.encounter_participant FORCE ROW LEVEL SECURITY;
CREATE POLICY owner_access ON ehr.encounter_participant TO hospital_owner USING(true) WITH CHECK(true);
CREATE POLICY clinician_access ON ehr.encounter_participant TO hospital_clinician USING(EXISTS(SELECT FROM ehr.encounter e WHERE e.id=encounter_id));
ALTER TABLE ehr.care_plan_activity ENABLE ROW LEVEL SECURITY;
ALTER TABLE ehr.care_plan_activity FORCE ROW LEVEL SECURITY;
CREATE POLICY owner_access ON ehr.care_plan_activity TO hospital_owner USING(true) WITH CHECK(true);
CREATE POLICY clinician_access ON ehr.care_plan_activity TO hospital_clinician USING(EXISTS(SELECT FROM ehr.care_plan p WHERE p.id=care_plan_id));
ALTER TABLE scheduling.appointment_participant ENABLE ROW LEVEL SECURITY;
ALTER TABLE scheduling.appointment_participant FORCE ROW LEVEL SECURITY;
CREATE POLICY owner_access ON scheduling.appointment_participant TO hospital_owner USING(true) WITH CHECK(true);
CREATE POLICY clinician_access ON scheduling.appointment_participant TO hospital_clinician USING(EXISTS(SELECT FROM scheduling.appointment a WHERE a.id=appointment_id));
CREATE POLICY registrar_access ON scheduling.appointment_participant TO hospital_registrar USING(EXISTS(SELECT FROM scheduling.appointment a WHERE a.id=appointment_id));
ALTER TABLE imaging.series ENABLE ROW LEVEL SECURITY;
ALTER TABLE imaging.series FORCE ROW LEVEL SECURITY;
CREATE POLICY owner_access ON imaging.series TO hospital_owner USING(true) WITH CHECK(true);
CREATE POLICY clinician_access ON imaging.series TO hospital_clinician USING(EXISTS(SELECT FROM imaging.study s WHERE s.id=study_id));
ALTER TABLE mpi.merge_history ENABLE ROW LEVEL SECURITY;
ALTER TABLE mpi.merge_history FORCE ROW LEVEL SECURITY;
CREATE POLICY owner_access ON mpi.merge_history TO hospital_owner USING(true) WITH CHECK(true);
CREATE POLICY clinician_access ON mpi.merge_history TO hospital_clinician USING(iam.has_patient_access(source_patient_id,'treatment') AND iam.has_patient_access(target_patient_id,'treatment'));
CREATE POLICY registrar_access ON mpi.merge_history TO hospital_registrar USING(iam.has_patient_access(source_patient_id,'registration') AND iam.has_patient_access(target_patient_id,'registration'));
CREATE FUNCTION audit.record_patient_access(p_patient_id bigint,p_purpose text,p_action text,p_request_id uuid,p_reason text) RETURNS bigint LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE rid bigint; BEGIN IF NOT iam.has_patient_access(p_patient_id,p_purpose) THEN RAISE EXCEPTION 'Patient access denied' USING ERRCODE='42501'; END IF; IF p_reason IS NULL OR length(btrim(p_reason))<5 THEN RAISE EXCEPTION 'Access reason required' USING ERRCODE='23514'; END IF; INSERT INTO audit.access_event(actor,patient_id,purpose,action,request_id,reason) VALUES(session_user,p_patient_id,p_purpose,p_action,p_request_id,p_reason) RETURNING id INTO rid; RETURN rid; END$$;
CREATE VIEW billing.v_patient_identity WITH(security_barrier=true) AS SELECT id AS patient_id,mrn,'Пациент '||right(mrn,4) AS display_label FROM mpi.patient WHERE iam.has_patient_access(id,'billing');
CREATE VIEW billing.v_invoice_balance WITH(security_invoker=true) AS SELECT i.id,i.patient_id,i.invoice_number,i.payer_id,i.currency_code,i.status,i.issued_at,i.due_at,coalesce(l.total_amount,0)::numeric(18,2) total_amount,coalesce(p.paid_amount,0)::numeric(18,2) paid_amount,(coalesce(l.total_amount,0)-coalesce(p.paid_amount,0))::numeric(18,2) outstanding_amount FROM billing.invoice i LEFT JOIN(SELECT invoice_id,sum(net_amount+tax_amount) total_amount FROM billing.invoice_line GROUP BY invoice_id)l ON l.invoice_id=i.id LEFT JOIN(SELECT invoice_id,sum(amount) paid_amount FROM billing.payment_allocation GROUP BY invoice_id)p ON p.invoice_id=i.id;
-- A line has no direct patient id: protect it through invoice visibility.
ALTER TABLE billing.invoice_line ENABLE ROW LEVEL SECURITY;
ALTER TABLE billing.invoice_line FORCE ROW LEVEL SECURITY;
CREATE POLICY owner_access ON billing.invoice_line TO hospital_owner USING(true) WITH CHECK(true);
CREATE POLICY billing_access ON billing.invoice_line TO hospital_billing USING(EXISTS(SELECT FROM billing.invoice i WHERE i.id=invoice_id));
CREATE VIEW ehr.v_patient_timeline WITH(security_invoker=true) AS SELECT e.id encounter_id,e.patient_id,e.type_code,e.status,e.started_at,e.ended_at,d.name department,s.display_name attending FROM ehr.encounter e JOIN org.department d ON d.id=e.department_id JOIN org.staff s ON s.id=e.attending_staff_id;
CREATE VIEW inventory.v_stock AS SELECT l.id lot_id,i.sku,i.name,lo.code location_code,l.expires_on,b.quantity,i.reorder_point,b.quantity<i.reorder_point AS below_reorder FROM inventory.stock_balance b JOIN inventory.lot l ON l.id=b.lot_id JOIN inventory.item i ON i.id=l.item_id JOIN inventory.location lo ON lo.id=b.location_id;
CREATE MATERIALIZED VIEW analytics.daily_activity AS SELECT e.started_at::date activity_date,e.department_id,d.name department,e.type_code,count(*) encounters,count(DISTINCT e.patient_id) patients,round(avg(extract(epoch FROM (e.ended_at-e.started_at))/60)::numeric,2) average_duration_minutes FROM ehr.encounter e JOIN org.department d ON d.id=e.department_id GROUP BY 1,2,3,4;
CREATE UNIQUE INDEX daily_activity_key ON analytics.daily_activity(activity_date,department_id,type_code);
CREATE MATERIALIZED VIEW analytics.monthly_revenue AS SELECT date_trunc('month',i.issued_at)::date reporting_month,i.payer_id,p.name payer,i.currency_code,count(*) invoices,sum(i.total_amount)::numeric(20,2) billed,sum(i.paid_amount)::numeric(20,2) paid,sum(i.outstanding_amount)::numeric(20,2) outstanding FROM billing.v_invoice_balance i JOIN billing.payer p ON p.id=i.payer_id WHERE i.status='issued' GROUP BY 1,2,3,4;
CREATE UNIQUE INDEX monthly_revenue_key ON analytics.monthly_revenue(reporting_month,payer_id,currency_code);
CREATE VIEW analytics.bed_occupancy AS SELECT d.id department_id,d.name department,count(*) FILTER(WHERE b.active) active_beds,count(*) FILTER(WHERE b.active AND EXISTS(SELECT FROM adt.bed_stay s WHERE s.bed_id=b.id AND clock_timestamp()<@s.occupied_during)) occupied_beds FROM org.bed b JOIN org.room r ON r.id=b.room_id JOIN org.department d ON d.id=r.department_id GROUP BY 1,2;
CREATE VIEW analytics.v_catalog AS SELECT n.nspname schema_name,c.relname table_name,obj_description(c.oid,'pg_class') description,c.reltuples::bigint estimated_rows,CASE WHEN c.relkind='p' THEN (SELECT sum(pg_total_relation_size(pt.relid))::bigint FROM pg_partition_tree(c.oid::regclass) pt WHERE pt.isleaf) ELSE pg_total_relation_size(c.oid) END total_bytes,c.relrowsecurity row_security,c.relforcerowsecurity forced_row_security FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE c.relkind IN('r','p') AND NOT c.relispartition AND n.nspname NOT IN('ext','pg_catalog','information_schema');
-- Comments are deliberately present on every domain table and every column.
DO $$DECLARE r record; BEGIN FOR r IN SELECT n.nspname,c.relname,c.oid FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE c.relkind IN('r','p','v','m') AND NOT c.relispartition AND n.nspname NOT IN('ext','pg_catalog','information_schema') LOOP EXECUTE format('COMMENT ON %s %I.%I IS %L',CASE WHEN (SELECT relkind FROM pg_class WHERE oid=r.oid)='v' THEN 'VIEW' WHEN (SELECT relkind FROM pg_class WHERE oid=r.oid)='m' THEN 'MATERIALIZED VIEW' ELSE 'TABLE' END,r.nspname,r.relname,'Hospital reference model / '||r.nspname||' / '||replace(r.relname,'_',' ')||'. Synthetic demonstration; see DATA_MODEL.md for semantics.'); END LOOP; FOR r IN SELECT n.nspname,c.relname,a.attname,a.attnum,c.oid FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE c.relkind IN('r','p') AND NOT c.relispartition AND a.attnum>0 AND NOT a.attisdropped AND n.nspname NOT IN('ext','pg_catalog','information_schema') LOOP EXECUTE format('COMMENT ON COLUMN %I.%I.%I IS %L',r.nspname,r.relname,r.attname,CASE WHEN r.attname='patient_id' THEN 'Internal MPI key; patient/encounter identity enforced with composite foreign keys where applicable.' WHEN r.attname='id' THEN 'Internal immutable surrogate key; identity sequence.' WHEN r.attname='public_id' THEN 'Opaque UUID for external references; does not confer authorization.' WHEN r.attname LIKE '%_at' THEN 'Instant stored as timestamptz; display timezone Asia/Qyzylorda.' WHEN r.attname LIKE '%during' OR r.attname LIKE '%period' THEN 'Validity interval; temporal constraints apply. Use half-open [start,end) convention.' ELSE replace(r.attname,'_',' ')||'; see table constraints and DATA_MODEL.md.' END); END LOOP; END$$;
COMMENT ON TABLE ehr.observation IS 'Typed clinical measurements, monthly RANGE partitions 2024–2027; exactly one value, unit checked against catalog. Partition key is part of primary key.';
COMMENT ON TABLE ehr.note_version IS 'Append a new version to amend a signed note. Signed versions cannot be updated/deleted. SHA-256 detects body differences; it is not a qualified electronic signature.';
COMMENT ON TABLE inventory.stock_movement IS 'Append-only inventory ledger. A per-location/lot balance is updated under row lock; negative stock rolls back the movement and dispensing transaction.';
COMMENT ON TABLE billing.payment_allocation IS 'Append-only allocation, serialized by payment and invoice row locks. Currency, payer, patient identity and available balances are checked.';
COMMENT ON TABLE iam.access_grant IS 'Patient/purpose/time-limited authorization; keyed to session_user via application_user. Custom session GUCs are not an authorization source.';
COMMENT ON TABLE integration.outbox IS 'Transactional outbox envelope; use SELECT FOR UPDATE SKIP LOCKED in a short transaction; delivery requires an external worker.';
COMMENT ON TABLE audit.event IS 'Append-only DML metadata; actor=session_user. Baseline explicitly denotes synthetic load. No full clinical bodies are duplicated. Superusers remain trusted.';
COMMENT ON TABLE mpi.patient IS 'Master patient index; synthetic MRN and UUID. No real national identifiers or contact details. Row-level access is deny-by-default.';
COMMENT ON TABLE lab.report_result IS 'Versioned diagnostic report membership; composite keys prevent patient mismatch. Further amendment workflow requires application orchestration.';
GRANT USAGE ON SCHEMA ref,org TO hospital_clinician,hospital_registrar,hospital_billing;
GRANT SELECT ON ALL TABLES IN SCHEMA ref,org TO hospital_clinician,hospital_registrar,hospital_billing;
GRANT USAGE ON SCHEMA iam TO hospital_clinician,hospital_registrar,hospital_billing;
GRANT USAGE ON SCHEMA mpi,ehr,adt,scheduling,lab,imaging,pharmacy TO hospital_clinician;
GRANT SELECT ON ALL TABLES IN SCHEMA mpi,ehr,adt,scheduling,lab,imaging,pharmacy TO hospital_clinician;
GRANT INSERT,UPDATE ON ehr.condition,ehr.allergy,ehr.observation,ehr.clinical_note,ehr.note_version,ehr.care_plan,ehr.care_plan_activity TO hospital_clinician;
GRANT USAGE,SELECT ON ALL SEQUENCES IN SCHEMA ehr TO hospital_clinician;
GRANT USAGE ON SCHEMA mpi,scheduling TO hospital_registrar;
GRANT SELECT ON ALL TABLES IN SCHEMA mpi,scheduling TO hospital_registrar;
GRANT UPDATE(family_name,given_name,birth_date,administrative_gender) ON mpi.patient TO hospital_registrar;
GRANT UPDATE(status,reason_text) ON scheduling.appointment TO hospital_registrar;
GRANT USAGE ON SCHEMA billing TO hospital_billing;
GRANT SELECT ON ALL TABLES IN SCHEMA billing TO hospital_billing;
GRANT USAGE ON SCHEMA analytics TO hospital_analyst;
GRANT SELECT ON analytics.daily_activity,analytics.monthly_revenue,analytics.bed_occupancy TO hospital_analyst;
GRANT USAGE ON SCHEMA audit TO hospital_auditor,hospital_clinician,hospital_registrar,hospital_billing;
GRANT SELECT ON audit.event,audit.access_event TO hospital_auditor;
CREATE POLICY auditor_access ON audit.access_event TO hospital_auditor USING(true);
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA ref,org,iam,mpi,ehr,adt,scheduling,lab,imaging,pharmacy,inventory,billing,quality,integration,audit,ops FROM PUBLIC;
GRANT EXECUTE ON FUNCTION iam.has_patient_access(bigint,text),audit.record_patient_access(bigint,text,text,uuid,text) TO hospital_clinician,hospital_registrar,hospital_billing;
-- Partition tables themselves must never be queried by runtime roles: bypass of parent RLS.
DO $$DECLARE r record; BEGIN FOR r IN SELECT n.nspname,c.relname FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE c.relispartition AND c.relkind IN('r','p') AND n.nspname='ehr' LOOP EXECUTE format('REVOKE ALL ON %I.%I FROM hospital_clinician,hospital_registrar,hospital_billing,hospital_analyst,hospital_auditor',r.nspname,r.relname); END LOOP; END$$;
ALTER DEFAULT PRIVILEGES FOR ROLE hospital_owner REVOKE EXECUTE ON FUNCTIONS FROM PUBLIC;
INSERT INTO ops.schema_migration VALUES('06',clock_timestamp(),'RLS, auditing, runtime grants, analytics and documentation comments');
COMMIT;
-- Analyze only application-owned relations; shared system catalogs are administrator territory.
DO $$DECLARE r record; BEGIN FOR r IN SELECT n.nspname,c.relname FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE c.relkind IN('r','p','m') AND NOT c.relispartition AND n.nspname IN('ref','org','mpi','iam','ehr','adt','scheduling','lab','imaging','pharmacy','inventory','billing','quality','integration','audit','analytics','ops') LOOP EXECUTE format('ANALYZE %I.%I',r.nspname,r.relname); END LOOP; END$$;
